-- =============================================================
--  캠핑 플랫폼 DB 마이그레이션 V7
--  Base    : V6까지 적용 완료 상태 기준
--  DB      : MySQL 8.0+
--  변경    : 캠핑 플랫폼 더미 데이터 (선택 8개 테이블, 각 20건)
--  대상    : users, camps, camp_wishlists, reservations, payments, posts, comments, reviews
--  Base    : 실제 camping_db 덤프(2026-07-07) 기준
--  주의    : ID 명시 지정 → 빈 테이블에서 실행 권장. users.image_id 는 NULL(=images 의존 없음).
--  반영    : users 에 profile_image 없음 / reviews 에 user_id 없음 /
--            reservations.total_price(NOT NULL) / camps.price·addr2 / camps CHECK(content_id XOR owner_id).
--  구성    : payments·reviews 는 reservation 과 1:1(UQ) → 20개 예약 모두 완료(RESERVED)+결제+리뷰.
--  참고    : Flyway 는 접속 URL 의 DB 로 자동 실행됨.
--            Workbench 로 직접 테스트할 때는 먼저 camping_db 를 선택할 것.
-- =============================================================


SET FOREIGN_KEY_CHECKS = 0;

